import 'package:flutter/material.dart';
import '../models/item_model.dart';import '../services/firestore_service.dart';import '../utils/app_colors.dart';import '../widgets/item_image.dart';import 'item_form_page.dart';import 'item_detail_page.dart';
class InventoryPage extends StatelessWidget{
 const InventoryPage({super.key});
 @override Widget build(BuildContext context){final service=FirestoreService();return Scaffold(backgroundColor:AppColors.background,appBar:AppBar(automaticallyImplyLeading:false,title:const Text('Inventaris')),
 floatingActionButton:FloatingActionButton.extended(backgroundColor:AppColors.primary,foregroundColor:Colors.white,onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ItemFormPage())),icon:const Icon(Icons.add),label:const Text('Tambah barang')),
 body:StreamBuilder<List<ItemModel>>(stream:service.getItems(),builder:(context,s){if(s.hasError)return const Center(child:Text('Gagal memuat inventaris.'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final items=s.data!;final a=items.where((e)=>e.status=='Available').length;final b=items.length-a;
 return ListView(padding:const EdgeInsets.fromLTRB(18,8,18,100),children:[
 Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AppColors.primary,AppColors.secondary]),borderRadius:BorderRadius.circular(22)),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Ringkasan inventaris',style:TextStyle(color:Colors.white70)),const SizedBox(height:5),Text(items.length.toString()+' Barang',style:const TextStyle(color:Colors.white,fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:12),Text(a.toString()+' tersedia • '+b.toString()+' dipinjam',style:const TextStyle(color:Colors.white))])),const Icon(Icons.inventory_2_rounded,color:Colors.white,size:48)])),
 const SizedBox(height:20),if(items.isEmpty)const Padding(padding:EdgeInsets.all(40),child:Center(child:Text('Belum ada barang. Tekan Tambah barang untuk memulai.')))else ...items.map((i)=>_card(context,service,i))
 ]);}) );}
 Widget _card(BuildContext context,FirestoreService service,ItemModel i){final available=i.status=='Available';final date=i.createdAt==null?'Tanggal belum tersedia':MaterialLocalizations.of(context).formatMediumDate(i.createdAt!.toDate());
 return Container(margin:const EdgeInsets.only(bottom:13),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20),boxShadow:[BoxShadow(color:Colors.black.withValues(alpha:.04),blurRadius:12,offset:const Offset(0,4))]),child:InkWell(borderRadius:BorderRadius.circular(20),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ItemDetailPage(item:i))),child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[
 ClipRRect(borderRadius:BorderRadius.circular(15),child:ItemImage(item:i,width:88,height:88)),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
 Text(i.itemName,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:15,color:AppColors.navy)),const SizedBox(height:4),Text(i.code+' • '+i.category,style:const TextStyle(color:AppColors.muted,fontSize:11)),const SizedBox(height:7),Text('Ditambahkan: '+date,style:const TextStyle(color:AppColors.muted,fontSize:10)),const SizedBox(height:7),_status(i.status)])),
 if(available)PopupMenuButton<String>(onSelected:(v)async{if(v=='edit'){Navigator.push(context,MaterialPageRoute(builder:(_)=>ItemFormPage(item:i)));}else{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Hapus barang?'),content:Text('Barang '+i.itemName+' akan dihapus.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Batal')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Hapus'))]));if(ok==true){try{await service.deleteItem(i.id);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Barang berhasil dihapus.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Gagal: $e')));}}}},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:ListTile(leading:Icon(Icons.edit_outlined),title:Text('Edit'))),PopupMenuItem(value:'delete',child:ListTile(leading:Icon(Icons.delete_outline),title:Text('Hapus')))])else const Padding(padding:EdgeInsets.all(10),child:Icon(Icons.lock_outline,color:AppColors.borrowed))
 ]))));}
 Widget _status(String v){final a=v=='Available';final c=a?AppColors.available:AppColors.borrowed;return Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:5),decoration:BoxDecoration(color:c.withValues(alpha:.11),borderRadius:BorderRadius.circular(20)),child:Text(a?'Tersedia':'Sedang dipinjam',style:TextStyle(color:c,fontSize:10,fontWeight:FontWeight.bold)));}
}
